/* HEXA BATTLEGROUNDS setup — PART 55 OF 83. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-odd-13', 'odd', 'mission', 'Odd One Out', 'logic', 1, array['any','learning','hr','office','social','food']::text[], 'Each teammate sees four words. One does not belong. Name the odd one out in all three lists.', '{"scout":{"title":"List 1","body":"Coffee · Tea · Juice · Bread","mono":false,"big":true},"decoder":{"title":"List 2","body":"Winter · Summer · Autumn · Morning","mono":false,"big":true},"intel":{"title":"List 3","body":"Cotton · Silk · Wool · Steel","mono":false,"big":true}}'::jsonb, '[{"label":"List 1 (Scout)","accept":["BREAD"]},{"label":"List 2 (Decoder)","accept":["MORNING"]},{"label":"List 3 (Intel)","accept":["STEEL"]}]'::jsonb, false, 3, 200, 'Find what three of the words have in common.', 'BREAD: not a drink | MORNING: not a season | STEEL: not a fabric', null, 25, 'published'), ('mission-odd-14', 'odd', 'mission', 'Odd One Out', 'logic', 1, array['any','learning','hr','office','social','food']::text[], 'Each teammate sees four words. One does not belong. Name the odd one out in all three lists.', '{"scout":{"title":"List 1","body":"Piano · Drum · Tabla · Bongo","mono":false,"big":true},"decoder":{"title":"List 2","body":"Ruby · Emerald · Sapphire · Marble","mono":false,"big":true},"intel":{"title":"List 3","body":"Kolkata · Chennai · Kochi · Bhopal","mono":false,"big":true}}'::jsonb, '[{"label":"List 1 (Scout)","accept":["PIANO"]},{"label":"List 2 (Decoder)","accept":["MARBLE"]},{"label":"List 3 (Intel)","accept":["BHOPAL"]}]'::jsonb, false, 3, 200, 'Find what three of the words have in common.', 'PIANO: not a drum | MARBLE: not a gemstone | BHOPAL: not on the coast', null, 25, 'published'), ('mission-clock-0', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"The shuttle arrives at 06:15. It left 145 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"A training runs from 13:20 to 16:20. How many MINUTES long is it?","mono":true,"big":false},"intel":{"title":"Clock 3","body":"The shuttle arrives at 06:20. It left 200 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["0350"]},{"label":"Clock 2 (Decoder)","accept":["180"]},{"label":"Clock 3 (Intel)","accept":["0300"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '0350: 06:15 − 145 min | 180: 180 minutes | 0300: 06:20 − 200 min', null, 25, 'published'), ('mission-clock-1', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"It is 10:35. The meeting starts in 2 h 50 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"It is 10:35. The meeting starts in 0 h 55 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"A training runs from 09:25 to 10:55. How many MINUTES long is it?","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["1325"]},{"label":"Clock 2 (Decoder)","accept":["1130"]},{"label":"Clock 3 (Intel)","accept":["90"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '1325: 10:35 + 170 min | 1130: 10:35 + 55 min | 90: 90 minutes', null, 25, 'published'), ('mission-clock-2', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"It is 16:35. The meeting starts in 2 h 25 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"It is 14:20. The meeting starts in 1 h 5 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"It is 18:30. The meeting starts in 0 h 50 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["1900"]},{"label":"Clock 2 (Decoder)","accept":["1525"]},{"label":"Clock 3 (Intel)","accept":["1920"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '1900: 16:35 + 145 min | 1525: 14:20 + 65 min | 1920: 18:30 + 50 min', null, 25, 'published'), ('mission-clock-3', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"A training runs from 11:25 to 14:35. How many MINUTES long is it?","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"The shuttle arrives at 18:45. It left 155 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"A training runs from 07:55 to 08:50. How many MINUTES long is it?","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["190"]},{"label":"Clock 2 (Decoder)","accept":["1610"]},{"label":"Clock 3 (Intel)","accept":["55"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '190: 190 minutes | 1610: 18:45 − 155 min | 55: 55 minutes', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-clock-4', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"A training runs from 17:55 to 20:55. How many MINUTES long is it?","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"It is 07:20. The meeting starts in 1 h 55 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"The shuttle arrives at 14:00. It left 135 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["180"]},{"label":"Clock 2 (Decoder)","accept":["0915"]},{"label":"Clock 3 (Intel)","accept":["1145"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '180: 180 minutes | 0915: 07:20 + 115 min | 1145: 14:00 − 135 min', null, 25, 'published'), ('mission-clock-5', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"The shuttle arrives at 14:10. It left 160 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"A training runs from 16:05 to 17:20. How many MINUTES long is it?","mono":true,"big":false},"intel":{"title":"Clock 3","body":"The shuttle arrives at 10:00. It left 140 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["1130"]},{"label":"Clock 2 (Decoder)","accept":["75"]},{"label":"Clock 3 (Intel)","accept":["0740"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '1130: 14:10 − 160 min | 75: 75 minutes | 0740: 10:00 − 140 min', null, 25, 'published'), ('mission-clock-6', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"A training runs from 17:15 to 19:55. How many MINUTES long is it?","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"It is 09:10. The meeting starts in 0 h 45 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"A training runs from 12:35 to 15:40. How many MINUTES long is it?","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["160"]},{"label":"Clock 2 (Decoder)","accept":["0955"]},{"label":"Clock 3 (Intel)","accept":["185"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '160: 160 minutes | 0955: 09:10 + 45 min | 185: 185 minutes', null, 25, 'published'), ('mission-clock-7', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"A training runs from 16:10 to 19:40. How many MINUTES long is it?","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"The shuttle arrives at 19:10. It left 50 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"The shuttle arrives at 07:00. It left 215 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["210"]},{"label":"Clock 2 (Decoder)","accept":["1820"]},{"label":"Clock 3 (Intel)","accept":["0325"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '210: 210 minutes | 1820: 19:10 − 50 min | 0325: 07:00 − 215 min', null, 25, 'published'), ('mission-clock-8', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"It is 16:10. The meeting starts in 0 h 55 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"It is 09:25. The meeting starts in 0 h 45 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false},"intel":{"title":"Clock 3","body":"It is 07:20. The meeting starts in 1 h 35 min. What time does it start? (24-hour, like 14:35)","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["1705"]},{"label":"Clock 2 (Decoder)","accept":["1010"]},{"label":"Clock 3 (Intel)","accept":["0855"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '1705: 16:10 + 55 min | 1010: 09:25 + 45 min | 0855: 07:20 + 95 min', null, 25, 'published'), ('mission-clock-9', 'clock', 'mission', 'Shift Clock', 'maths', 1, array['any','office','parking','access','learning']::text[], 'Three time puzzles, one per teammate. Times are 24-hour (type 14:35 or 1435).', '{"scout":{"title":"Clock 1","body":"The shuttle arrives at 07:10. It left 135 minutes earlier. When did it leave? (24-hour, like 09:05)","mono":true,"big":false},"decoder":{"title":"Clock 2","body":"A training runs from 15:10 to 16:35. How many MINUTES long is it?","mono":true,"big":false},"intel":{"title":"Clock 3","body":"A training runs from 14:30 to 15:25. How many MINUTES long is it?","mono":true,"big":false}}'::jsonb, '[{"label":"Clock 1 (Scout)","accept":["0455"]},{"label":"Clock 2 (Decoder)","accept":["85"]},{"label":"Clock 3 (Intel)","accept":["55"]}]'::jsonb, false, 3, 200, 'Do hours first, then minutes. 60 minutes make an hour.', '0455: 07:10 − 135 min | 85: 85 minutes | 55: 55 minutes', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); alter table events add column if not exists demo boolean not null default false; alter table events add column if not exists card_set text; alter table teams add column if not exists is_bot boolean not null default false; create index if not exists events_card_set_idx on events(card_set) where card_set is not null; create table if not exists app_secrets ( key text primary key, value text not null ); create table if not exists bots ( team_id uuid primary key references teams(id) on delete cascade, arena_id uuid not null references arenas(id) on delete cascade, manual boolean not null default false, skill real not null default 0.75, goal text, goal_at timestamptz, done_loc text, wait_until timestamptz, think_for uuid, think_until timestamptz, think_ok boolean ); create index if not exists bots_arena_idx on bots(arena_id); create table if not exists bot_players ( player_id uuid primary key references players(id) on delete cascade, team_id uuid not null references teams(id) on delete cascade, idx int not null, token text not null ); create index if not exists bot_players_team_idx on bot_players(team_id); create table if not exists bot_clock ( arena_id uuid primary key references arenas(id) on delete cascade, at timestamptz not null default now() ); do $$ declare t text; begin foreach t in array array['app_secrets', 'bots', 'bot_players', 'bot_clock'] loop execute format('alter table %I enable row level security', t); execute format('revoke all on table %I from anon, authenticated', t); end loop; end $$; create or replace function _card_secret() returns text language plpgsql security definer set search_path = public as $$ declare v text; begin select value into v from app_secrets where key = 'card_pepper'; if v is null then insert into app_secrets(key, value) values ('card_pepper', _new_token() || _new_token()) on conflict (key) do nothing; select value into v from app_secrets where key = 'card_pepper'; end if; return v; end $$; create or replace function _card_pin(p_secret text, p_number int) returns text language plpgsql security definer set search_path = public as $$ declare v text; i int := 0; h text; begin loop h := _hash(_card_secret() || '|pin|' || coalesce(p_secret, '') || '|' || p_number || '|' || i); v := lpad(((('x' || substr(h, 1, 12))::bit(48)::bigint) % 1000000)::text, 6, '0'); exit when not _weak_pin(v) or i >= 20; i := i + 1; end loop; return v; end $$; create or replace function host_fixed_cards(p_token text, p_secret text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; e events; ar arenas; t teams; i int; v_num int; v_pin text; v_salt text; v_size int; v_set text; v_out jsonb := '[]'::jsonb; v_new int := 0; begin v_ev := _auth_host(p_token); select * into e from events where id = v_ev; if e.host_secret_hash <> _hash(e.host_salt || coalesce(p_secret, '')) then insert into audit_log(event_id, actor, action, ok) values (v_ev, 'host', 'fixed_cards_denied', false); return jsonb_build_object('error', 'HOST_AUTH'); end if; v_size := least(15, greatest(1, _cfg(v_ev, 'arena_size'))); v_set := substr(_hash(_card_secret() || '|set|' || p_secret), 1, 10); for ar in select * from arenas where event_id = v_ev order by number loop for i in 1..v_size loop v_num := (ar.number - 1) * v_size + i; v_pin := _card_pin(p_secret, v_num); v_salt := _new_token(); select * into t from teams where event_id = v_ev and number = v_num; if t.id is null then continue when ar.phase <> 'lobby'; insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, ar.id, v_num, null, v_salt, _hash(v_salt || v_pin)) returning * into t; perform _add_item(t.id, 'pistol', 1); perform _add_item(t.id, 'medkit', 1); v_new := v_new + 1; else update teams set pin_salt = v_salt, pin_hash = _hash(v_salt || v_pin) where id = t.id; end if; v_out := v_out || jsonb_build_object('number', v_num, 'name', t.name, 'pin', v_pin, 'bus', t.bus, 'map', (select number from arenas where id = t.arena_id)); end loop; end loop; update events set card_set = v_set where id = v_ev; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'fixed_cards', jsonb_build_object('created', v_new, 'set', v_set)); return jsonb_build_object('set', v_set, 'created', v_new, 'squads', v_out); end $$; create or replace function card_event(p_set text) returns jsonb language sql stable security definer set search_path = public as $$ select (select jsonb_build_object('code', code, 'name', name) from events where card_set = lower(left(coalesce(p_set, ''), 20)) and not demo order by created_at desc limit 1) $$;
